// ── SESSION TOUCH ─────────────────────────────────────
// Updates updatedAt so 30min timeout resets on each message
// ──────────────────────────────────────────────────────
const sessionId = $('WhatsApp Trigger').first().json.sessionId || 'default_session';
const staticData = $getWorkflowStaticData('global');
if (staticData.sessions && staticData.sessions[sessionId]) {
  staticData.sessions[sessionId].updatedAt = new Date().toISOString();
}
return [$input.first()];

// ── ERROR FORMATTER ──────────────────────────────────
// Formats any node error into a clean admin alert email.
// ──────────────────────────────────────────────────────
const err = $input.first().json.error || {};
const nodeName = err.node?.name || 'Unknown node';
const errorMsg = err.message || JSON.stringify(err);
const sessionId = $('WhatsApp Trigger').first()?.json?.messages[0]?.from || 'unknown';
const chatInput = $('WhatsApp Trigger').first()?.json?.messages[0]?.text?.body || 'unknown';
const timestamp = new Date().toISOString();

const htmlBody = `<!DOCTYPE html><html><body style='font-family:Arial,sans-serif;padding:24px;max-width:560px'>
<div style='background:#b91c1c;padding:20px;border-radius:10px 10px 0 0;text-align:center'>
