// ── DATE TABLE GENERATOR ──────────────────────────────────
// Pre-calculates the next occurrence of each weekday
// Injects into prompt so LLM never does date math itself
// ──────────────────────────────────────────────────────────

const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const today = new Date();
today.setHours(0, 0, 0, 0);

const nextDates = {};
let daysAhead = 1;

// Find next occurrence of each weekday (skip Sunday = 0)
while (Object.keys(nextDates).length < 6 && daysAhead <= 14) {
  const candidate = new Date(today);
  candidate.setDate(today.getDate() + daysAhead);
  const dayNum = candidate.getDay();

  if (dayNum !== 0 && !nextDates[dayNames[dayNum]]) {
    const yyyy = candidate.getFullYear();
    const mm = String(candidate.getMonth() + 1).padStart(2, '0');
    const dd = String(candidate.getDate()).padStart(2, '0');
    nextDates[dayNames[dayNum]] = {
      date: `${yyyy}-${mm}-${dd}`,
      display: `${dayNames[dayNum]} ${candidate.getDate()} ${candidate.toLocaleString('en', { month: 'long' })} ${yyyy}`
    };
  }
  daysAhead++;
}

// Build the table string for the prompt
const dateTable = Object.entries(nextDates)
  .sort((a, b) => a[1].date.localeCompare(b[1].date))
  .map(([day, val]) => `- Next ${day} = ${val.date} (${val.display})`)
  .join('\n');

// Pass through all existing input data + add dateTable
return [{ json: {
  ...($input.first().json),
  dateTable,
  todayISO: today.toISOString().split('T')[0]
}}];

