const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
if (!dateRegex.test(d.meetingDate || '')) {
  return [{ json: { status: 'CHATTING', reply: 'Could you confirm the meeting date in YYYY-MM-DD format?', data: null } }];
}

const meetingYear = parseInt((d.meetingDate || '').split('-')[0]);
const currentYear = new Date().getFullYear();
if (meetingYear < currentYear) {
  return [{ json: { status: 'CHATTING', reply: `There seems to be a mix-up with the year — could you confirm the meeting date again? We are booking for ${currentYear} onwards.`, data: null } }];
}

const [yyyy, mo, dd] = (d.meetingDate).split('-').map(Number);
const storedDate = new Date(Date.UTC(yyyy, mo - 1, dd));
const dayOfWeek = storedDate.getUTCDay();
if (dayOfWeek === 0) {
  return [{ json: { status: 'CHATTING', reply: 'We do not have slots on Sundays. Could you suggest a Monday to Saturday date?', data: null } }];
}

const todayUTC = new Date();
todayUTC.setUTCHours(0, 0, 0, 0);
if (storedDate < todayUTC) {
  return [{ json: { status: 'CHATTING', reply: 'That date has already passed. Could you suggest an upcoming date? We are available Monday to Saturday, 09:00 to 18:00.', data: null } }];
}

const timeRegex = /^([01]\d|2[0-3]):[0-5]\d$/;
if (!timeRegex.test(d.meetingTime || '')) {
  return [{ json: { status: 'CHATTING', reply: 'Could you clarify the meeting time? We are available between 09:00 and 18:00.', data: null } }];
}
const [h, m] = d.meetingTime.split(':').map(Number);
